[2855]={o="Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",r={"Thick Armor Kit (6)","Wildvine (1)"}},
[2856]={o="Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",r={"Turtle Scale Breastplate (2)","Turtle Scale Gloves (2)","Wildvine (1)"}},
[2857]={o="Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.",r={"Nightscape Tunic (2)","Nightscape Headband (2)","Wildvine (1)"}},
