[2859]={o="Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.",r={"Turtle Scale Helm (2)","Turtle Scale Bracers (2)","Wildvine (2)"}},
[2860]={o="Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff."},
[2861]={o="Speak with Tabetha in Dustwallow Marsh."},
[2862]={o="Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.",r={"Woodpaw Gnoll Mane (10)"}},
