[9]={o="Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet.",r={"Erntebehüter (20)"},s="Bauer Saldean",e="Bauer Saldean"},
[10]={o="Erforscht das Schicksal von Unterfeldmesser Scrimshank und bringt entweder ihn oder seine Feldmesserausrüstung nach Gadgetzan zum Leitenden Feldmesser Fizzledowser.",r={"Scrimshanks Feldmesser-Ausstattung (1)"}},
