[8410]={o="Bath'rah der Windbehüter möchte, dass Ihr jeweils eine Probe Luft, Feuer, Erde und Wasser für ihn sammelt.",r={"Elementarluft (1)","Elementarfeuer (1)","Elementarerde (1)","Elementarwasser (1)"}},
[8411]={o="Bringt Bath'rah dem Windbehüter die Elemente Erde, Luft, Feuer und Wasser.",r={"Elementarluft (1)","Elementarerde (1)","Elementarfeuer (1)","Elementarwasser (1)"}},
[8412]={o="Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem.",r={"Blutunterlaufenes Spinnenauge (8)","Dicke schwarze Klaue (8)"}},
[8413]={o="Bringt Bath'rah dem Windbehüter die Voodoofedern.",r={"Gelbe Voodoofeder (2)","Blaue Voodoofeder (2)","Grüne Voodoofeder (2)"}},
[8414]={o="Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den westlichen Pestländern.",r={"Geißelstein des Dieners (20)"}},
[8415]={o="Sprecht mit Kommandanten Ashlam Valorfist an der Chillwindspitze."},
[8416]={o="Bringt den gereinigten Geißelstein zu Kommandant Ashlan Valorfist an der Chillwindspitze."},
[8417]={o="Sprecht mit dem gefallenen Helden der Horde am Eingang zu den verwüsteten Landen."},
[8418]={o="Bringt die Voodoofedern zu Ashlam Valorfist.",r={"Gelbe Voodoofeder (2)","Blaue Voodoofeder (2)","Grüne Voodoofeder (2)"}},
[8419]={o="Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.",r={"Teufelsstoff (1)"}},
[8420]={o="Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.",r={"Teufelsstoff (1)"}},
[8421]={o="Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald.",r={"Faules Holz (10)","Blutgiftessenz (4)"}},
[8422]={o="Bringt 6 Voodoofedern von den Trollen aus dem versunkenen Tempel.",r={"Gelbe Voodoofeder (2)","Blaue Voodoofeder (2)","Grüne Voodoofeder (2)"}},
[8423]={o="Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück.",r={"Hölleneber (7)"}},
[8424]={o="Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück.",r={"Adept der Schattenanbeter (20)","Kultist der Schattenanbeter (10)","Rohling der Schattenanbeter (20)"}},
[8425]={o="Bringt die Voodoofedern der Trolle im versunkenen Tempel zu dem gefallenen Helden der Horde.",r={"Gelbe Voodoofeder (2)","Blaue Voodoofeder (2)","Grüne Voodoofeder (2)"}},
[8438]={o="Bringt 3 Ehrenabzeichen des Arathibeckens zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.",r={"Ehrenabzeichen des Arathibeckens (3)"}},
[8446]={o="Sucht nach jemandem, der die Bedeutung des in Alpträume gehüllten Gegenstands entschlüsseln kann. Vielleicht kann Euch ein Druide von großer Macht weiterhelfen."},
[8447]={o="Wartet, bis Bewahrer Remulos in Moonglade den von Alpträumen eingehüllten Gegenstand gereinigt hat.",r={"Legenden erwachen. (1)"}},
[8460]={o="Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt.",r={"Krieger der Totenwaldfelle (6)","Pfadfinder der Totenwaldfelle (6)","Gärtner der Totenwaldfelle (6)"}},
[8461]={o="Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück.",r={"Höhlenbehüter der Totenwaldfelle (6)","Rächer der Totenwaldfelle (6)","Schamane der Totenwaldfelle (6)"}},
[8462]={o="Reist nach Norden entlang der Hauptstraße des Teufelswalds und sprecht mit einem Furbolg names Nafien. Er hält außerhalb des Eingangs zur Holzschlundfeste Wache."},
[8464]={o="Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich genau außerhalb des Eingangs zur Holzschlundfeste in Winterspring.",r={"Schamane der Winterfelle (8)","Höhlenbehüter der Winterfelle (8)","Ursa der Winterfelle (8)"}},
[8465]={o="Durchquert die Holzschlundfeste und verlasst sie in Richtung Winterspring. Sprecht mit Salfa, die außerhalb des Eingangs zur Holzschlundfeste Wache steht."},
[8466]={o="Ihr habt Euch mir gegenüber mehr als bewiesen, doch um das Vertrauen meiner misstrauischen Brüder und Schwestern zu gewinnen, ist es noch ein weiter Weg. Keine Sorge, ich werde Euch dabei behilflich sein, auch diese letzte Hürde zu überwinden. Einige Furbolgs der Totenwaldfelle tragen einen auffälligen Kopfschmuck. Dieser wäre ein ausreichender Beweis, für Euren Kampf gegen unsere verderbten Geschwister. Bringt mir die Federn der von Euch erbeuteten Kopfschmucke. Für jeweils fünf Federn die Ihr bei mir abgebt, wird sich Euer Ruf unter den Einwohnern der Holzschlundfeste verbessern.",r={"Kopfputzfeder der Totenwaldfelle (5)"}},
[8467]={o="Ihr habt Euch mir gegenüber mehr als bewiesen, doch um das Vertrauen meiner misstrauischen Brüder und Schwestern zu gewinnen, ist es noch ein weiter Weg. Keine Sorge, ich werde Euch dabei behilflich sein, auch diese letzte Hürde zu überwinden. Einige Furbolgs der Totenwaldfelle tragen einen auffälligen Kopfschmuck. Dieser wäre ein ausreichender Beweis, für Euren Kampf gegen unsere verderbten Geschwister. Bringt mir die Federn der von Euch erbeuteten Kopfschmucke. Für jeweils fünf Federn die Ihr bei mir abgebt, wird sich Euer Ruf unter den Einwohnern der Holzschlundfeste verbessern.",r={"Kopfputzfeder der Totenwaldfelle (5)"}},
[8469]={o="Ihr habt Euch mein Vertrauen hart erarbeitet, &lt;Name&gt;. Doch bis meine Brüder und Schwestern Euch genauso akzeptieren, wie ich es tue, ist es noch ein weiter Weg. Ihr könntet jedoch etwas für mich tun, um diesen Prozess zu beschleunigen. Die Furbolgs der Winterfelle sind dafür bekannt, dass sie zum Schutz vor dunklen Mächten Geisterperlen bei sich tragen. Aber auch diese mächtigen Artefakte vermochten es nicht, die Verderbnis aufzuhalten und so sind die Winterfelle dieser Macht erlegen. Bringt mir die Geisterperlen gefallener Furbolgs der Winterfelle. Für jeweils fünf Geisterperlen die Ihr bei mir abgebt, wird sich Euer Ruf unter den Einwohnern der Holzschlundfeste verbessern.",r={"Geisterperlen der Winterfelle (5)"}},
[8470]={o="Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furlbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist.",r={"Holzschlundfeste: (1)"}},
[8471]={o="Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furlbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist.",r={"Holzschlundfeste: (1)"}},
[8481]={o="Stellt die Fackel zur Dämonenbeschwörung im Eingang der Höhle des Oberhäuptlings der Winterfelle, im Lager der Winterfellfurbolgs auf. Besiegt den Dämon und erlangt die Essenz von Xandivious für Gorn Einauge in der Holzschlundfeste.",r={"Essenz von Xandivious (1)","Holzschlundfeste: (1)"}},
[8484]={o="Bringt das Friedensangebot der Holzschlundfeste zu König Magni Bronzebeard in Ironforge.",r={"Holzschlundfeste: (1)"}},
[8485]={o="Bringt das Friedensangebot der Holzschlundfeste zu Thrall in Orgrimmar.",r={"Holzschlundfeste: (1)"}},
[8492]={o="Bringt 20 Kupferbarren zu Sergeant Stonebrow im Militärviertel in Ironforge.",r={"Kupferbarren (20)"}},
[8493]={o="Bringt 20 Kupferbarren zu Sergeant Stonebrow beim Landeplatz in Dun Morogh.",r={"Kupferbarren (20)"}},
