[2238]={o="Encontre Onin MacHammar em Gnomeregan.",s="Hulfdan Barbanegra"},
[2239]={o="Leve o relatório de Onin para Hulfdan em Altaforja.",e="Hulfdan Barbanegra"},
[2240]={o="Leia o Diário de Baelog, explore a câmara oculta, depois fale com o Prospector Lançatroz.",r={"(1)","Explore a Câmara Oculta (1)"}},
