[2584]={o="Leve 3 Pulmões de Javali Destroçado, 2 Tenazes de Escórpode e 1 Cérebro de Basilisco para o Mago Sangrento Drazial.",r={"Pulmão de Javali Destroçado (3)","Tenaz de Escórpode (2)","Cérebro de Basilisco (1)"}},
[2585]={o="Leve 3 Tenazes de Escórpode, 2 Moelas de Abutre e 1 Pulmão de Javali Destroçado para o Mago Sangrento Drazial.",r={"Tenaz de Escórpode (3)","Moela de Abutre (2)","Pulmão de Javali Destroçado (1)"}},
[2586]={o="Leve três Tenazes de Escórpode, duas Moelas de Abutre e um Pulmão de Javali Destroçado para o Mago Sangrento Drazial.",r={"Tenaz de Escórpode (3)","Moela de Abutre (2)","Pulmão de Javali Destroçado (1)"}},
