[2641]={o="Sguisha, em Geringontzan, quer que você colete um Tragão Violeta e fale novamente com ela.",r={"Tragão Violeta (1)"}},
[2661]={o="Sguisha quer que você leve o Pó Violeta para Marin Nublacuca em Geringontzan."},
