[2747]={r={"Ovo Extraordinário (1)"}},
[2748]={r={"Ovo Fecundo (1)"}},
[2749]={o="Ovos de hipogrifo comuns vingam mais ou menos metade das vezes. Fazemos todo o possível para chocá-los e, com um pouco de sorte, eles vão vingar.",r={"Ovo Comum (1)"}},
[2750]={r={"Ovo Gorado (1)"}},
