[5927]={o="Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão."},
[5928]={o="Fale com Turak Runa Totem no Platô dos Anciãos, que fica no Penhasco do Trovão."},
[5929]={o="Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.",r={"Procure o Espírito do Grande Urso e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. (1)"},s="Dendrite Stellardor",e="Dendrite Stellardor"},
[5930]={o="Procure o Espírito do Grande Urso na região noroeste da Clareira da Lua e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. Quando terminar, fale novamente com Dendrite Stellardor no Refúgio Noturno, que fica na Clareira da Lua.",r={"Procure o Espírito do Grande Urso e aprenda o que ele tem a compartilhar com você sobre a natureza do urso. (1)"}},
[5931]={o="Volte a Darnassus e fale com Mathrengyl Ursivagus no Enclave Cenariano.",s="Dendrite Stellardor",e="Mathrengyl Ursivagus"},
[5932]={o="Volte ao Penhasco do Trovão e fale com Turak Runa Totem no Platô dos Anciãos."},
[5941]={o="Leve a Coleção de Relíquias para Crona em Andorhal."},
[5942]={o="Leve a Chave de Josefo ao Baú de Josefo."},
[5943]={o="Escolte a Caravana Gizelton pelas Ruínas de Mannoroc. Fale com o Smid no Acampamento do Rabiscafuso para receber a recompensa.",r={"Escolte a Caravana Gizelton pelas Ruínas de Mannoroc. (1)"}},
[5944]={o="Escolte Taelan Fordring para fora de Amparo.",r={"Redenção? (1)"}},
[5961]={o="Fale com Nathanos, o Arauto da Praga nas Terras Pestilentas Orientais. Dizem que ele fixou residência no Sítio dos Marris."},
[5981]={o="Ripárion Glaciares quer que você mate 4 Gigantes Friomalho e 4 Preservadores Friomalho.",r={"Gigante Friomalho (4)","Preservador Friomalho (4)"}},
[6001]={o="Aplique Poeira de Lua Cenariana na Pedra Luniscante de Auberdine para trazer Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui. Fale com Mathrengyl Ursivagus em Darnassus quando você terminar.",r={"Enfrente Lunagarra e ganhe a força de corpo e coração que ele possui. (1)"},s="Mathrengyl Ursivagus",e="Mathrengyl Ursivagus"},
[6002]={o="Aplique Poeira Lunar Cenariana na Pedra Luniscante entre Mulgore e os Sertões para evocar Lunagarra. Então, enfrente Lunagarra e ganhe a força de corpo e coração que ele possui. Fale com Turak Runa Totem no Penhasco do Trovão quando terminar.",r={"Enfrente Lunagarra e ganhe a força de corpo e coração que ele possui. (1)"}},
[6004]={o="Mate 2 Socorristas Escarlate, 2 Caçadores Escarlate, 2 Magos Escarlate e 2 Cavaleiros Escarlate antes de voltar a Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais.",r={"Socorrista Escarlate (2)","Caçador Escarlate (2)","Mago Escarlate (2)","Cavaleiro Escarlate (2)"}},
[6021]={o="Leve a Cabeça de Zaeldarr ao Zelador Alen na Capela Esperança da Luz.",r={"Cabeça de Zaeldarr (1)"}},
[6022]={o="Vá ao Cruzamento de Corin, a leste, e mate membros do Flagelo que habitam a cidade. Colete 7 pedaços de Putrefação Viva em menos de 10 minutos. Use o Almofariz e Pilão para moer a Putrefação Viva, de maneira a transformá-la em Putrefação Coagulada.",r={"Putrefação Coagulada (1)","Putrefação Viva (7)"}},
[6023]={o="Mate o Guarda-caça Eiras e o Fidalgo Durgen antes de voltar à Kirsta Sombrafunda, nas Terras Pestilentas Ocidentais.",r={"Guarda-caça Eiras (1)","Fidalgo Durgen (1)"}},
[6024]={o="Mate o Infiltrador Hameya. Use a chave dele no Monturo de Terra atrás da Chácara Secreta.",r={"Chave de Hameya (1)"}},
[6025]={o="Entre em Amparo e encontre um lugar alto de onde possa ver a cidade e avaliar as forças da Cruzada Escarlate. Então fale novamente com Kirsta Sombrafunda nas Terras Pestilentas Ocidentais.",r={"(1)","Examine Amparo de um ponto alto (1)"}},
[6026]={o="Leandro Leonardo quer que você pegue 2 Barras de Tório, 1 Bastão Dourado, 8 Bombas de Alto-explosivo e 8 Gatilhos Instáveis. Você terá que encontrar um ferreiro e um engenheiro para esses itens.",r={"Barra de Tório (2)","Bastão Dourado (1)","Bomba de Alto-explosivo (8)","Gatilho Instável (8)"}},
[6027]={o="Pegue o Livro dos Anciãos e entregue-o para Azore Albamorte na torre de Ethel Rethor.",r={"Livro dos Anciãos (1)"}},
[6028]={o="Entregue o Relatório de Visteterna à Oficial Argêntea Cândida no Acampamento Ventogelante, que fica nas Terras Pestilentas Ocidentais."},
[6029]={o="Entregue o Relatório de Visteterna ao Oficial Argênteo Garush no Baluarte, nas Terras Pestilentas Ocidentais."},
[6030]={o="Entregue o livro \"Estudos sobre Comunicação com Espíritos\" ao Duque Nicolau Zverenhoff na Capela Esperança da Luz, que fica nas Terras Pestilentas Orientais."},
[6031]={o="Leve 30 cortes de Runatrama para Meilosh no Domínio dos Presamatos.",r={"Runatrama (30)"}},
[6032]={o="Leve 2 cortes de Lunatrama para Meilosh no Domínio dos Presamatos.",r={"Lunatrama (2)"}},
[6041]={o="Viaje ao Bosque Pestilento, a noroeste da Esperança da Luz. Destrua 8 Estruturas do Flagelo usando o Composto Químico Especial do Leandro na Marca de Detonação plantada dentro de cada construção. Os Zigurates e Abatedouros foram marcados por instrução de Leandro. Assim que você plantar a bomba, deixe a estrutura e contemple seu trabalho. A propósito, o Composto Químico Especial do Leandro é bastante... instável.",r={"Estruturas do Flagelo destruídas (8)"}},
[6042]={o="Mate 20 Quirópragos Nóxios e 10 Quirópragos Monstruosos. Fale novamente com Nathanos Arauto da Praga quando você tiver terminado.",r={"Quiróprago Nóxio (20)","Quiróprago Monstruoso (10)"}},
[6061]={o="Use o Bastão de Adestramento para domar um Pinote Adulto. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Yaw Crina Cortante na Aldeia Casco Sangrento.",r={"Dome um pinote adulto (1)"}},
[6062]={o="Use o Bastão de Adestramento para domar uma Mosquetusco Hediondo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha.",r={"Dome um Mosquetusco Hediondo (1)"}},
[6063]={o="Use o Bastão de Adestramento para domar uma Tocaieira Lenhateia. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Dazalar em Dolanaar.",r={"Dome uma Tocaieira Lenhateia (1)"}},
[6064]={o="Use o Bastão de Adestramento para domar uma Rochetusco Grande. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Grif Selvacuore em Kharanos.",r={"Dome um Rochetusco Grande (1)"},s="Grif Selvacuore",e="Grif Selvacuore"},
