[6082]={o="Use o Bastão de Adestramento para domar um Escorpídeo Encouraçado. Pratique sua habilidade e depois fale novamente com Thotar no Monte Navalha.",r={"Dome um Escorpídeo Encouraçado (1)"}},
[6083]={o="Use o Bastão de Adestramento para domar uma Surfatisco. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Thotar no Monte Navalha.",r={"Dome um Surfatisco (1)"}},
[6084]={o="Use o Bastão de Adestramento para domar uma Leopardo da Neve. Pratique sua habilidade e depois fale novamente com Grif Selvacuore em Kharanos.",r={"Dome um Leopardo da Neve (1)"},s="Grif Selvacuore",e="Grif Selvacuore"},
[6085]={o="Use o Bastão de Adestramento para domar um Urso Garra de Gelo. Pratique sua habilidade e depois devolva o Bastão de Adestramento a Grif Selvacuore em Kharanos.",r={"Dome um Urso Garra de Gelo (1)"},s="Grif Selvacuore",e="Grif Selvacuore"},
