[8992]={o="Use o Braseiro de Sinalização para evocar o espírito de Kormok e então mate-o. Fale novamente com Bodley na Montanha Rocha Negra, com o Amuleto do Lorde Valthalak restaurado e o Braseiro de Sinalização.",r={"Kormok (1)","Amuleto do Lorde Valthalak (1)","Parte Direita do Amuleto do Lorde Valthalak (1)"}},
[8994]={o="Colete 40 Braceletes de Rocha Negra e consiga um Frasco de Poder Supremo. Leve tudo para Bodley, dentro da Montanha Rocha Negra.",r={"Bracelete de &nbsp;Rocha Negra (40)","Frasco de Poder Supremo (1)"}},
[8995]={o="Use o Braseiro de Sinalização para evocar o Lorde Valthalak. Acabe com ele e use o Amuleto do Lorde Valthalak no cadáver. Em seguida, devolva o Amuleto do Lorde Valthalak ao Espírito de Lorde Valthalak.",r={"Lorde Valthalak (1)","Amuleto do Lorde Valthalak (1)"}},
[8996]={o="Fale novamente com Bodley na Montanha Rocha Negra e dê a ele o Braseiro de Sinalização.",r={"Braseiro de Sinalização (1)"}},
[8997]={o="Fale com Deliana na Sala do Trono em Altaforja."},
[8998]={o="Fale com Mokvar no Castelo Grommash, que fica no Vale da Sabedoria, em Orgrimmar."},
[8999]={o="Dê a Deliana seu Capucho do Coração Selvagem e seu Colete do Coração Selvagem.",r={"Capucho do Coração Selvagem (1)","Colete do Coração Selvagem (1)"}},
