[1839]={o="Поговорите с Ула'елеком из Дуротара."},
[1840]={o="Обратитесь к Орму Каменному Копыту из Громового Утеса."},
[1841]={o="Поговорите с Велорой Нители из Подгорода."},
[1842]={o="Принесите 7 нераздвоенных копыт сатиров Ула'елеку в Дуротар, в деревню Сен'джин.",r={"Нераздвоенное копыто сатира (7)"}},
[1843]={o="Спасибо, Коммибро. Эти рукавицы – мое величайшее достижение. Возьми их. Ты окажешь мне честь, если пойдешь в них в бой."},
[1844]={o="Принести Орму Каменному Копыту из Громового Утеса гальванизированный рог.",r={"Гальванизированный рог (1)"}},
[1845]={o="Возьми этот шлем. Тебя привели ко мне великие свершения, и если Матери-земле будет угодно... тебе предстоит немало подвигов."},
[1846]={o="Принесите 8 крепких берцовых костей Драконьей Пасти Велоре Нители в Подгород.",r={"Прочная берцовая кость Драконьей Пасти (8)","Берцовая кость орка из клана Драконьей Пасти (999)"}},
[1847]={o="Вот твои набедренники, Большойзмей. Ну как, подходят? Или надо что-то менять? Мне хочется угодить заказчику! По крайней мере всегда хотелось. Теперь ремесло утратило прежнюю прелесть. Но все лучше, чем быть безмозглым рабом Плети! Наверное."},
[1848]={o="Тебе несомненно пришлось пролить немало крови, чтобы справиться с моим заданием, Коммибро. Вот плод твоих трудов. Носи с удовольствием. Как-нибудь заходи, расскажешь, как он тебе пригодился в бою."},
[1858]={o="Украдите ключ Тазана, откройте сумку Тазана и отнесите содержимое сумки Терзоку в расселину Теней в Оргриммаре.",r={"Дневник Тазана (1)","Ключ Тазана (1)"}},
[1859]={o="Поговорите с Терзоком в расселине Теней в Оргриммаре."},
[1860]={o="Поговорите с Джиннией Пушкой в Штормграде.",s="Залдимар Вефхеллт",e="Джинния Пушка"},
[1861]={o="Отнесите пробу воды из Зеркального озера Джиннии Пушке из Штормграда.",r={"Проба воды Зеркального озера (1)"},s="Джинния Пушка",e="Джинния Пушка"},
[1878]={o="Опять ты здесь? Если ты несешь еще пять бурдюков с водой Скитальцев Пустыни, то тебя ждет еще один именной полевой набор!",r={"Бурдюк с водой Скитальцев Пустыни (5)"}},
