[2298]={o="스톰윈드로 가서 칼잡이 렌직을 찾아야 합니다.",s="훌프단 블랙비어드",e="칼잡이 렌직"},
[2299]={o="아이언포지로 가서 훌프단 블랙비어드와 대화하십시오.",s="호그럴 바칸",e="훌프단 블랙비어드"},
[2300]={o="스톰윈드로 가서 칼잡이 렌직을 찾아야 합니다.",s="케린 실비우스",e="칼잡이 렌직"},
[2318]={o="성기사의 일지를 번역할 수 있는 이를 찾아야 합니다. 그런 자가 있을만한 가장 가까운 곳은 황야의 땅에 있는 카르가스입니다."},
[2338]={o="자칼에게 목걸이를 빌려주면 그에 대한 보답으로 일지를 번역해 줄 것입니다."},
[2339]={o="울다만에서 목걸이에 필요한 보석 3개와 마력원천을 회수한 후 카르가스에 있는 자칼 모스멜드에게 가져다주어야 합니다. 자칼의 말에 의하면 울다만에서 가장 강한 피조물을 처치하면 마력원천을 얻을 수 있다고 합니다. 일지의 내용을 보니 루비는 어둠괴철로단의 방어진에 숨겨져 있습니다. 토파즈는 얼라이언스 드워프 근처에 있는 트로그 구역 중 하나에 있는 항아리에 숨겨져 있습니다. 사파이어는 트로그의 우두머리인 그림로크가 가지고 있습니다. 마력원천은 울다만에서 가장 강한 피조물을 처치하면 얻을 수 있습니다.",r={"부서진 목걸이의 루비 (1)","부서진 목걸이의 사파이어 (1)","부서진 목걸이의 토파즈 (1)","부서진 목걸이의 마력원천 (1)"}},
[2340]={o="오그리마에 있는 드란 드로퍼스에게 회수한 목걸이와 보석을 가져다주어야 합니다."},
[2341]={o="카르가스에 있는 자칼 모스멜드를 만나 그의 실험이 성공했는지 알아보십시오."},
[2342]={o="울다만의 남쪽 대전당에 있는 궤짝에서 가레트가의 보물을 찾아 언더시티에 있는 그에게 가져가야 합니다.",r={"가레트가의 보물 (1)"}},
[2359]={o="데피아즈단 탑 열쇠를 훔쳐 데피아즈단 탑으로 숨어 들어간 후, 그늘숲 궤짝에 무엇이 들어 있는지 밝혀 내야 합니다. 알아낸 모든 정보를 가지고 스톰윈드에 있는 마티아스 쇼에게 돌아가야 합니다. 켈넌의 보고서을 읽고 탑에 대한 정보를 얻으십시오.",r={"클라벤 몰트워크의 일지 (1)","데피아즈단 탑 열쇠 (1)"},s="첩보원 켈넌",e="단장 마티아스 쇼"},
[2360]={o="서부 몰락지대로 가서 첩보원 켈넌을 찾아 보고를 받아야 합니다.",s="단장 마티아스 쇼",e="첩보원 켈넌"},
[2361]={o="이 목걸이를 기꺼이 당신에게 주겠소. 당신은 나에게 헤아릴 수 없이 귀중한 일을 해 주었소. 정말 고맙소이다. 자, 자랑스럽게 걸고 다니시오. 그리고 누가 만든 것인지 크게, 그리고 많이 말해 주시오! 실제로 목걸이가 저주받지 않았다는 사실도 곁들여주면 더 고맙겠군."},
[2378]={o="오그리마로 가서 어둠의 틈에 있는 셴툴과 대화해야 합니다."},
[2379]={o="어둠의 틈에 있는 잔도잔과 대화하십시오."},
[2380]={o="오그리마의 어둠의 틈에 있는 셴툴과 대화하십시오."},
[2381]={o="톱니항에 있는 비운의 레닉스에게 남쪽바다해적단 보물을 가져가야 합니다. 레닉스의 기계장치에서 E.C.A.C.와 도둑 도구를 얻는 것도 잊지 마십시오. 임무를 완수하려면 이 두 가지가 모두 필요합니다. 유별나게 공격적인 앵무새에게 맞서게 되면 E.C.A.C.를 사용하십시오!",r={"남쪽바다해적단 보물 (1)"}},
[2382]={o="톱니항으로 가서 비운의 레닉스와 대화하십시오."},
[2383]={o="간결한 양피지를 읽어보고 프랑에게 양피지를 가져가야 합니다."},
[2398]={o="울다만에서 밸로그를 찾아야 합니다."},
[2399]={o="데날란이 정원에 심은 잎에서 싹이 트고 자랐습니다. 바르르 떠는 모습이 마치 누군가 뽑아주기를 바라고 안달하는 듯 합니다.",s="싹튼 잎",e="싹튼 잎"},
[2418]={o="황야의 땅에 있는 리글퍼즈에게 덴트리움 마법석 8개와 안알레움 마법석 8개를 가져가야 합니다.",r={"덴트리움 마법석 (8)","안알레움 마법석 (8)"}},
[2438]={o="돌라나르에 있는 탈론카이 스위프트루트에게 에메랄드의 꿈 흡입기를 가져다주어야 합니다.",r={"에메랄드의 꿈 흡입기 (1)"},s="탈론카이 스위프트루트",e="탈론카이 스위프트루트"},
[2439]={o="아이언포지 은행에 있는 디니타 스톤맨틀에게 사례 보증 서류를 가져가야 합니다."},
[2440]={o="썬더 블러프에 있는 베나 윈터후프에게 사례 보증 서류를 가져가야 합니다."},
[2458]={o="진흙늪 북쪽에 있는 투자개발회사 탑으로 가서 검은손 도적단의 비밀 요원인 감독관 피줄과 접촉해야 합니다. 탑이 보이면 섬광탄포를 사용해 감독관 피줄에게 당신이 도착했음을 알리십시오. 섬광탄은 2번 발사해야 하며, 그 후 감독관 피줄에게 다가가 검은손 도적단 /경례를 해야 합니다. 피줄은 자기가 모르는 자는 무조건 처치하려 들기 때문에 정확한 순서대로 수행해야 합니다."},
[2459]={o="돌라나르에 있는 탈론카이 스위프트루트가 나무옹이일족 비술사 7명을 처치하고 잃어버린 보석을 찾아달라고 부탁했습니다.",r={"나무옹이일족 비술사 (7)","탈론카이의 보석 (1)","나무옹이일족 목걸이 (1)"},s="탈론카이 스위프트루트",e="탈론카이 스위프트루트"},
[2460]={o="셴툴에게 검은손 도적단 /경례를 해 보이십시오.",r={"검은손 도적단 경례 수행 (1)"}},
[2478]={o="현장감독 실릭시즈에게서 실릭시즈의 탑 열쇠를 훔쳐낸 다음, 돌연변이 투자개발회사 일꾼 2명과 투자개발회사 순찰대원 2명, 그리고 투자개발회사 망꾼 2명을 처치해야 합니다. 총감독 갤리윅스를 암살하고 그의 머리카락을 손에 넣은 후, 갤리윅스의 금고를 열고 잔질의 변화된 혼합물을 훔쳐내야 합니다. 그 혼합물과 갤리윅스의 머리카락을 오그리마에 있는 셴툴에게 가져다주고 다음 지시를 받으십시오.",r={"돌연변이 투자개발회사 일꾼 (2)","투자개발회사 망꾼 (2)","투자개발회사 순찰대원 (2)","갤리윅스의 머리카락 (1)","실릭시즈의 탑 열쇠 (1)","잔질의 변화된 혼합물 (1)"}},
[2479]={o="힐스브래드 구릉지의 타렌 밀농장으로 가서 서지 히노트에게 잔질의 혼합물 견본을 전해야 합니다. 타렌 밀농장으로 가려면 먼저 비행선을 타고 언더시티로 가야 합니다. 도착하면 남쪽 길을 따라 은빛소나무 숲을 지나 힐스브래드 쪽으로 가야 합니다. 표지판을 따라 가십시오!"},
[2480]={o="서지 히노트가 해독제를 만드는 동안 기다려야 합니다.",r={"해독제 완성 (1)"}},
[2498]={o="레엘리안 그린스파이어가 알아메스 호수에 있는 데날란과 대화할 것을 부탁했습니다.",s="레엘리안 그린스파이어",e="데날란"},
[2499]={o="알아메스 호수에 사는 데날란이 오크나무괴물에게서 거대한 종양을 모아 달라고 부탁했습니다.",r={"거대한 종양 (1)"},s="데날란",e="데날란"},
[2500]={o="황야의 땅에서 필요한 재료를 구한 후 텔사마에 있는 가크 힐터치에게 돌아가야 합니다.",r={"대머리수리 모래주머니 (5)","바위산코요테 송곳니 (10)","바위 정령 파편 (5)"}},
[2501]={o="빈 요술 유리병을 황야의 땅에 있는 화염의 수호비룡에게 사용해야 합니다. 3개를 다 채우면 텔사마에 있는 가크 힐터치에게로 가져가야 합니다.",r={"용의 피가 담긴 유리병 (3)"}},
[2518]={o="다르나서스의 달의 신전에 있는 여사제 아무라가 여왕거미 사스라의 은빛 돌기를 가져다 달라고 부탁했습니다.",r={"은빛 돌기 (1)"},s="여사제 아무라",e="여사제 아무라"},
[2519]={o="수녀 아퀴네가 달의 신전에 있는 여사제 아무라와 대화할 것을 부탁했습니다.",s="수녀 아퀴네",e="여사제 아무라"},
[2520]={o="여사제 아무라가 달의 신전 중앙에 있는 샘에 사스라의 은빛 돌기를 제물로 바치고 돌아와 달라고 부탁했습니다.",r={"샘에 제물 바치기 (1)"},s="여사제 아무라",e="여사제 아무라"},
[2521]={o="저주받은 땅을 돌아다니다가 완전무결한 드레니시스트 구슬을 발견하면 수집가 굼이샤에게 가져가야 합니다. 이 보석은 아제로스를 통틀어 가장 희귀한 수정 중 하나로써 이곳 생물들이 지니고 있을 가능성도 있습니다. 완전무결한 드레니시스트 구슬을 수집해 갈 때마다 각각에 대해 보상을 받게 됩니다.",r={"완전무결한 드레니시스트 구슬 (1)"}},
[2522]={o="수집가 굼이샤에게 완전무결한 드레니시스트 구슬을 가져가야 합니다.",r={"완전무결한 드레니시스트 구슬 (1)"}},
[2523]={o="노래꽃인 듯한 식물을 찾았는데 병들고 오염되어 있습니다. 식물에서는 지독한 냄새가 풍겨나옵니다. 이 식물을 원래대로 되돌리려면 당장에라도 어떤 조치를 취해야 합니다.",r={"세나리온 식물 고약 (2)"}},
