[3792]={o="또 보는군. 내 연구는 순조롭게 진행 중이오. 하지만 여명초 5개만 더 있다면 정말 기쁠 것 같소. 뭐, 기뻐한다는 건 일종의 은유적인 표현이지. 곁에 오래 두면 둘수록 기분이 더 언짢아져서 말이오. 하지만 꾹 참고 이 연구를 끝내야만 하오.",r={"여명초 (5)"}},
[3801]={o="도시 주요 지역으로 통하는 열쇠를 얻고 싶다면 프랑클론 포지라이트와 대화하십시오."},
[3802]={o="파이너스 다크바이어를 처치하고 거대한 망치, 무쇠지옥을 회수해야 합니다. 무쇠지옥을 타우릿산의 제단으로 가져가서 프랑클론 포지라이트의 석상에 두어야 합니다.",r={"무쇠지옥 (1)"}},
[3803]={o="대드루이드께서는 세나리온 의회에서 진행 중인 연구에 사용할 여명초를 항상 찾고 계십니다. 한번에 10개씩 받는데, 가져온 이에게는 유용한 물건으로 보상해 주고 있어요. 10개를 구할 때마다 내게 알려 주면 그에 맞는 보상을 해드리지요.",r={"여명초 (10)"}},
[3804]={o="대드루이드님께서는 세나리온 의회의 운고로 분화구에 대한 연구에 쓸 여명초를 항상 찾고 계세요. 한 번에 10개씩 받는데, 가져온 이에게는 유용한 물건으로 보상해 주고 있답니다. 10개를 구할 때마다 제게 알려 주면 그에 맞게 보상해 드리겠어요.",r={"여명초 (10)"}},
[3821]={o="불타는 평원으로 가서 샤니 프라우드터스크에게 무슨 일이 있었는지 확인해야 합니다."},
[3822]={o="크롬그룰에게서 샤니의 코걸이를 찾아 카르가스에 있는 탈트라크에게 가져가야 합니다. 우레망치 바위굴에 있는 여러 광산과 동굴을 찾아봐야 합니다.",r={"샤니의 코걸이 (1)"}},
[3823]={o="불자루일족 오우거마법사 15마리, 불자루 오우거 7마리, 불자루일족 투사 7마리를 처치한 후 랄리우스에게 돌아가야 합니다.",r={"불자루일족 오우거마법사 (15)","불자루 오우거 (7)","불자루일족 투사 (7)"}},
[3824]={o="우레망치 바위굴의 서쪽 어딘가에서 고르테쉬를 찾아 처치하고 고르테쉬의 가면을 얻어 불타는 평원에 있는 랄리우스에게 가져가야 합니다.",r={"고르테쉬의 가면 (1)"}},
[3825]={o="고르테쉬의 가면을 가지고 가서 우레망치 바위굴의 꼭대기에 꽂아야 합니다. 창을 꽂을 부드러운 흙으로 덮인 고분을 찾도록 하십시오.",r={"고르테쉬의 가면 고정 (1)"}},
[3841]={o="버섯구름 봉우리에 있는 켄튼과 대화해야 합니다."},
[3842]={o="버섯구름 봉우리에 있는 켄튼에게 인내의 비약 2개를 가져가야 합니다.",r={"하급 인내의 비약 (2)"}},
[3843]={o="동부 내륙지로 깨지기 쉬운 화살요정용 알을 가져가서 아그나르 비스테이머와 대화하십시오. 1시간 내에 아그나르를 찾지 못하면 알 속의 새끼가 죽게 되니 서둘러야 합니다."},
