[3845]={o="가방 안에 든 물건을 조사해 그 주인에게 되돌려주어야 합니다.",r={"큰 나침반 (1)","두루마리 지도 (1)","사자머리 열쇠 (1)"}},
[3861]={o="특별 닭모이를 찾아 친구가 된 닭에게 돌아가야 합니다. 특별 닭모이를 주기 전에 닭을 찾으면 /환호해야 합니다.",r={"특별 닭모이 (1)"},s="닭",e="닭"},
[3881]={o="운고로 분화구에 있는 윌리덴 마샬에게 식량 상자와 탐사 장비를 가져가야 합니다.",r={"식량 상자 (1)","탐사 장비 (1)"}},
[3882]={o="운고로 분화구에 있는 스파크 닐마이너에게 공룡 뼈 8개를 가져가야 합니다.",r={"공룡 뼈 (8)"}},
[3883]={o="운고로 분화구에 있는 고리쉬 부화장에서 채집 약병을 사용해 고리쉬집 벽면 견본을 채취하십시오. 유충알이 매달려 있는 방을 찾아야 합니다. 운고로 분화구에 있는 홀라니에 마샬에게 고리쉬집 벽면 견본을 가져가야 합니다.",r={"고리쉬집 벽면 견본 (1)"}},
[3884]={o="운고로 분화구 어딘가에 있는 윌리덴 마샬에게 일지를 돌려줘야 합니다."},
[3901]={o="덜그럭거리는 해골 12명을 처치한 후, 데스넬에 있는 어둠의사제 사비스에게 돌아가야 합니다.",r={"덜그럭거리는 해골 (12)"}},
[3902]={o="데스넬과 그 주변에서 쓸만한 물건 6개를 찾아 죽음의경비병 살테인에게 돌아가야 합니다.",r={"쓸만한 물건 (6)"}},
