[5201]={o="리베른 프로스트윈드가 눈사태일족 주술사 5마리와 눈사태일족 펄볼그 5마리를 처치하도록 요청했습니다.",r={"눈사태일족 주술사 (5)","눈사태일족 펄볼그 (5)"}},
[5202]={o="자에데나르를 뒤져 이 붉은 열쇠의 용도를 알아내야 합니다."},
[5203]={o="아르코나린을 그녀의 방어구와 라이트포지가 있는 곳까지 호위해 간 후, 함께 어둠의 요새에서 빠져나가야 합니다. 그런 다음, 악령의 숲에 있는 제시 문보우를 찾아가 그녀의 친구들에게 무슨 일이 있었는지 알려 주어야 합니다.",r={"아르코나린을 호위해 어둠의 요새 탈출 (1)"}},
