[6981]={o="톱니항으로 가서 빛나는 조각에 대해 자세히 얘기해 줄 수 있는 이를 찾으십시오. 그에게 지시를 받아, 빛나는 조각을 전달해야 합니다.",r={"톱니항에서 빛나는 조각의 비밀을 알 만한 자와 대화하기 (1)"},e="팔라 세이지윈드"},
[7003]={o="페랄라스에서 눈에 띄는 아무 거인에게나 조브린의 형상축소기를 사용해 좀 더 다루기 쉬운 형태로 변환하십시오. 페랄라스의 잊혀진 해안 부두에 있는 조브린 팬대즐에게 변형된 거인들에게서 얻을 수 있는 축소화 잔류물 15개를 가져가야 합니다.",r={"축소화 잔류물 (15)"}},
[7028]={o="트라드릭 수정 조각상 25개를 모아서 잊혀진 땅에 있는 윌로우에게 가져가야 합니다.",r={"트라드릭 수정 조각상 (25)"}},
[7029]={o="마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다. 오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다. 녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 그늘수렵 마을에 있는 바르크 배틀스카에게 돌아가야 합니다.",r={"바일줄기 덩굴나무 치료 완료 (8)","가득 찬 감청석 약병 (1)"}},
[7041]={o="마라우돈에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채워야 합니다. 오염된 녹시온의 후예가 나타나게 하려면 바일줄기 덩굴나무 위에 감청색 약병에 담긴 액체를 부어야 합니다. 녹시온의 후예를 죽이는 방법으로 8개의 식물을 치료한 다음 나이젤의 야영지에 있는 탈렌드리아에게 돌아가야 합니다.",r={"바일줄기 덩굴나무 치료 완료 (8)","가득 찬 감청석 약병 (1)"}},
[7044]={o="셀레브라스의 홀 조각인 셀레브리안 마법봉과 셀레브리안 다이아몬드를 찾아야 합니다. 셀레브라스와 대화를 나눌 방법을 찾아야 합니다.",r={"셀레브리안 다이아몬드 (1)","셀레브리안 마법봉 (1)"}},
[7046]={o="회복된 셀레브라스가 셀레브라스의 홀을 만드는 동안 그를 도와야 합니다. 의식을 마친 후 그와 대화하십시오.",r={"고대의 홀 제작 (1)"}},
[7064]={o="공주 테라드라스를 해치우고 잊혀진 땅의 그늘수렵 마을 근처에 있는 셀렌드라에게 돌아가야 합니다.",r={"공주 테라드라스 (1)"}},
[7065]={o="공주 테라드라스를 해치우고 잊혀진 땅의 나이젤의 야영지에 있는 수호자 마란디스를 찾아가야 합니다.",r={"공주 테라드라스 (1)"}},
[7066]={o="달의 숲에 있는 수호자 레물로스를 찾아 생명의 씨앗을 전해 주어야 합니다."},
[7067]={o="추방자의 지시서를 읽은 다음 마라우돈에서 결속의 아뮬렛을 획득해서 잊혀진 땅 남부에 있는 켄타우로스 추방자에게 가져가야 합니다.",r={"결속의 아뮬렛 (1)","영혼의 아뮬렛 (1)"}},
[7068]={o="마라우돈에서 음영석 조각 10개를 모아서 오그리마에 있는 우텔나이에게 가져가야 합니다.",r={"음영석 조각 (10)"}},
[7070]={o="마라우돈에서 음영석 조각 10개를 모아서 먼지진흙 습지대의 해안에 위치한 테라모어에 있는 대마법사 테르보쉬에게 가져가야 합니다.",r={"음영석 조각 (10)"}},
[7201]={o="검은바위 나락으로 가서 원소의 정수 10개를 회수해야 합니다. 먼저 골렘이나 골렘 제조자부터 찾아보십시오. 비비안 라그레이브가 정령에 대해 중얼거리듯 얘기한 것도 기억이 납니다.",r={"원소의 정수 (10)"}},
[7321]={o="타렌 밀농장에 있는 크리스토프 제프코트에게 거북이 고기 10개와 독특한 양념을 가져가야 합니다.",r={"거북이 고기 (10)","독특한 양념 (1)"}},
[7341]={o="훌륭하군! 나는 약속을 지킬 줄 아는 타우렌이외다, &lt;race&gt; 친구. 화살을 받으시오.",r={"토륨 탄환 (200)"}},
[7342]={o="아니, 이런 말도 안 되는 일이?! 마지막으로 카라노스에서 온 탄환들은 완전히 불량품이었지 뭐예요! 이제 남은 거라곤 아무짝에도 쓸모없는 이 화살뿐이라고요! 대체 토륨 화살 500,000개로 뭘 어쩌겠어요? 흠... 이렇게 하면 어떨까요? 제게 토륨 탄환을 가져다주시면 토륨 화살로 교환해 드릴게요. 어때요?",r={"토륨 탄환 (200)"}},
[7383]={o="자수정 약병을 채운 다음 돌라나르에 있는 코리드라스 문레이지에게 가져가야 합니다.",r={"가득 찬 자수정 약병 (1)"},s="코리드라스 문레이지",e="코리드라스 문레이지"},
[7429]={o="그건 고르독 족쇄 열쇠라고 하는 물건이지. 이 오우거 얼간이들이 그렇게 부르더군. 이곳 오우거들이라면 누구나 지니고 있을 텐데, 어떤 오우거 녀석들이 지니고 있는지는 모르겠단 말이야. 경비병들이라면 갖고 있을 확률이 더 높겠지... 아니, 내가 지금 뭔 소리 하는 거야. 당신 벌써 그 열쇠 갖고 있지?! 그게 바로 그 열쇠야?!",r={"고르독 족쇄 열쇠 (1)"}},
[7441]={o="혈투의 전장으로 가서 푸실린이라는 임프를 찾으십시오. 어떤 수단을 써서라도 아즈토리딘의 마법서를 돌려받아야 합니다. 마법서를 회수하면 페랄라스의 라리스 정자에 있는 아즈토리딘에게 돌아가야 합니다.",r={"마법서 (1)"}},
[7461]={o="이몰타르의 감옥에 힘을 공급하는 다섯 개의 수정탑을 둘러싼 수호자들을 처치해야 합니다. 수정탑의 마력이 약해지면 이몰타르를 둘러싼 마법진도 분산될 것입니다. 이몰타르의 감옥에 들어가 그 심장부에 서 있는 사악한 이몰타르를 처치하고, 마지막으로 도서관에 있는 토르텔드린 왕자와 맞서 싸우십시오. 이 임무를 완수하면 안마당에 있는 셴드랄라 고대인에게 돌아가야 합니다.",r={"이몰타르 (1)","왕자 토르텔드린 (1)"}},
[7462]={o="도서관으로 되돌아가 셴드랄라의 보물을 찾아야 합니다. 임무 완수에 대한 보상을 받으십시오!"},
[7463]={o="혈투의 전장에 있는 굽이나무 지구로 가서 물의 정령인 히드로스폰을 처치하십시오. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스에게 돌아가야 합니다.",r={"히드로스폰의 정수 (1)"}},
[7481]={o="혈투의 전장을 뒤져 카리엘 윈탈루스를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 모자케 야영지에 있는 현자 코로루스크에게 돌아가야 합니다.",r={"스승 카리엘 윈탈루스 발견 (1)"}},
[7482]={o="혈투의 전장을 뒤져 카리엘 윈탈루스를 찾으십시오. 찾을 수 있는 정보는 모두 찾아 페더문 요새에 있는 학자 룬쏜에게 돌아가야 합니다.",r={"스승 카리엘 윈탈루스 발견 (1)"}},
[7483]={o="신속의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 2개, 그리고 영웅의 피 2개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 신속의 영석을 받아야 합니다.",r={"신속의 성서 (1)","온전한 검은 다이아몬드 (1)","눈부신 큰 결정 (2)","영웅의 피 (2)"}},
[7484]={o="집중의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 4개, 그리고 어둠의 허물 2개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 집중의 영석을 받아야 합니다.",r={"집중의 성서 (1)","온전한 검은 다이아몬드 (1)","눈부신 큰 결정 (4)","어둠의 허물 (2)"}},
[7485]={o="보호의 성서, 온전한 검은 다이아몬드 1개, 눈부신 큰 결정 2개, 그리고 닳아해진 누더기골렘 조각 1개를 혈투의 전장에 있는 현자 리드로스에게 갖다 주고 보호의 영석을 받아야 합니다.",r={"보호의 성서 (1)","온전한 검은 다이아몬드 (1)","눈부신 큰 결정 (2)","닳아해진 누더기골렘 조각 (1)"}},
[7486]={o="히드락시스의 궤짝에 든 보상을 차지하십시오."},
[7487]={o="검은바위 나락에 있는 화산 심장부 입구의 차원의 문으로 가서 핵 조각을 찾아야 합니다. 핵 조각을 갖고 검은바위 산에 있는 로소스 리프트웨이커에게로 돌아가십시오.",r={"핵 조각 (1)"}},
[7488]={o="페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어에게 레스텐드리스의 그물을 가져가야 합니다.",r={"레스텐드리스의 그물 (1)"}},
[7489]={o="페랄라스의 모자케 야영지에 있는 탈로 쏜후프에게 레스텐드리스의 그물을 가져가야 합니다.",r={"레스텐드리스의 그물 (1)"}},
[7490]={o="오그리마에 있는 대족장 스랄에게 오닉시아의 머리를 보여줘야 합니다."},
