[7509]={o="오닉시아가 달궈지지 않은 고대의 검에 화염 숨결을 내뿜도록 한 후, 달궈진 고대의 검을 뽑으십시오. 달궈진 고대의 검은 언제까지나 달구어져 있지 않으니 서둘러야 합니다. 마지막 단계로 오닉시아의 시체에 달궈진 고대의 검을 꽂으십시오. 이렇게 하면 쿠엘세라 검을 가질 수 있습니다.",r={"가공된 고대의 검 (1)","달궈진 고대의 검 (1)"}},
[7541]={o="자네가 가져온 펜던트를 우리 학자들이 살펴보는 데는 시간이 좀 걸릴 테지만, 호드를 위한 자네의 활약을 기리는 뜻에서 작은 선물을 주고 싶군. 고맙네. 자네가 한 일이 자네 자신은 물론 우리의 명예도 드높인 걸세."},
[7562]={o="불타는 평원에 있는 모르줄 블러드브링어와 대화하십시오."},
[7563]={o="불타는 평원에 있는 모르줄 블러드브링어에게 흉포한 올빼미야수의 피 30병을 가져가야 합니다.",r={"흉포한 올빼미야수의 피 (30)"}},
[7564]={o="불타는 평원에 있는 고르지키 와일드아이즈에게 피가 담긴 상자를 가져가야 합니다."},
[7581]={o="페랄라스에 있는 혈투의 전장으로 간 다음 굽이나무 지구에 서식하는 야생혈족 사티르로부터 사티르의 피 15개를 회수한 후 타락의 흉터에 있는 다이오에게 돌아가야 합니다.",r={"사티로스의 피 (15)"}},
[7582]={o="여명의 설원에 있는 검은속삭임 협곡에서 서식하는 헤더린의 악마들로부터 헤더린의 눈물 5개를 빼앗아야 합니다. 임무를 완수하면 타락의 흉터에 있는 다이오에게 돌아가십시오.",r={"헤더린의 눈물 (5)"}},
[7583]={o="타락의 흉터에서 파멸의수호병을 찾아내십시오. 빛나는 수정 감옥을 파멸의수호병에게 사용해야 합니다. 악마는 잡히지 않으려고 맹렬하게 공격할 테니 정신을 바짝 차리십시오. 성공하면 사로잡은 파멸의수호병을 타락의 흉터에 있는 다이오에게 데려가야 합니다.",r={"사로잡은 파멸수호병 (1)"}},
[7601]={o="악령의 숲에 있는 임프시와 대화하십시오."},
[7602]={o="악령의 숲에 있는 임프시가 이 세계의 각기 다른 세 개의 지역에서 완전무결한 지옥의 정수 3개를 가져와 달라고 부탁했습니다. 아즈샤라에는 레가쉬 사티로스들, 자에데나르에는 자에데나르 부대원들, 그리고 저주받은 땅에서는 지옥군단병 보초들이 각기 그 지역의 완전무결한 지옥의 정수를 갖고 있습니다. 완전무결한 지옥의 정수 3개를 다 모은 다음에는 악령의 숲에 있는 임프시에게 돌아가야 합니다.",r={"완전무결한 지옥의 정수 (아즈샤라) (1)","완전무결한 지옥의 정수 (자에데나르) (1)","완전무결한 지옥의 정수 (어둠의 문) (1)"}},
[7603]={o="악령의 숲에 있는 불벼락 골짜기를 수색해 크로쉬우스의 잔해를 찾아야 합니다. 찾으면 부근에서 지옥의 불꽃을 사용해 크로쉬우스를 되살리십시오. 크로쉬우스가 깨어나면 놈을 쓰러뜨린 후 크로쉬우스의 지옥핵을 꺼내야 합니다. 크로쉬우스의 지옥핵을 악령의 숲에 있는 전지전능한 나이비에게 가져다주십시오.",r={"크로쉬우스의 지옥핵 (1)"}},
[7604]={o="설퍼론 도면을 받으려면 설퍼론 주괴와 토륨 대장조합 계약서를 로크토스 다크바게이너에게 가져가야 합니다.",r={"설퍼론 주괴 (1)"}},
[7622]={o="15명이 살해 당하기 전에 인부 50명을 구해야 합니다. 이 임무를 완수하면 에리스 헤븐파이어와 대화하십시오. 살해 당한 농부의 수를 보려면 죽음의 말뚝을 보십시오.",r={"빛과 어둠의 균형 (1)"}},
[7623]={o="불타는 평원에 있는 고르지키에게서 어둠의 물약을 구입해야 합니다. 이 물약을 사용하여 자에데나르로 가서 군주 베인할로우와 대화하십시오."},
[7624]={o="울라텍과 맞서 싸운 후 자에데나르에 있는 베인할로우 군주에게 배신자의 증거를 가져가야 합니다.",r={"배신의 증거 (1)"}},
[7625]={o="우르단에게서 소로시안 별가루를 구입한 후, 불타는 평원에 있는 고르지키 와일드아이즈에게 가져가야 합니다.",r={"소로시안 별가루 (1)"}},
[7626]={o="불타는 평원에 있는 고르지키 와일드아이즈에게 암흑 강화의 비약 10개를 가져가야 합니다.",r={"암흑 강화의 비약 (10)"}},
[7627]={o="불타는 평원에 있는 고르지키 와일드아이즈에게 눈부신 큰 결정 6개와 검은무쇠 광석 25개를 가져가야 합니다.",r={"눈부신 큰 결정 (6)","검은무쇠 광석 (25)"}},
[7628]={o="불타는 평원에 있는 고르지키 와일드아이즈에게 검은용 비늘 35개를 가져가야 합니다.",r={"검은용 비늘 (35)"}},
[7629]={o="단지 안에 든 임프를 스칼로맨스에 있는 연금술 실험대로 가져가야 합니다. 양피지가 완성되면 단지를 고르지키 와일드아이즈에게 되돌려 주십시오.",r={"양피지 제작 (1)"}},
[7630]={o="불타는 평원에 있는 고르지키에게 아케이나이트 주괴 3개를 가져가야 합니다.",r={"아케이나이트 주괴 (3)"}},
[7631]={o="모르줄의 지시서를 잘 읽으십시오. 소로시안 공포마를 소환해 물리친 후 그 영혼을 결속시켜야 합니다."},
[7632]={o="단단한 고대의 잎사귀의 주인을 찾아야 합니다. 행운을 빕니다, &lt;name&gt;. 세상은 아주 넓으니까요."},
[7634]={o="고대정령 하스타트가 다 자란 푸른용 힘줄을 가져다 달라고 부탁했습니다. 이것을 찾으면 악령의 숲에 있는 하스타트에게 가져가십시오.",r={"다 자란 푸른용 힘줄 (1)"}},
[7635]={o="고대정령 스토마가 다 자란 검은용 힘줄을 가져다 달라고 부탁했습니다. 이것을 찾으면 악령의 숲에 있는 스토마에게 가져가십시오.",r={"다 자란 검은용 힘줄 (1)"}},
[7636]={o="타락한 악령의 4인조를 찾아 처치해야 합니다. 매혹의 시몬 광기의 클린프랑 학살자 솔레노르 파멸의 인도자 아토리우스 위 넷의 혼을 갈무리하여 악령의 숲에 있는 고대정령 바르투스에게 돌아가십시오. 이들의 위치에 대한 단서는 바르투스가 주는 돌껍질을 참조하십시오. 이 임무는 반드시 혼자서 완수해야 합니다.",r={"시몬의 혼 (1)","클린프랑의 혼 (1)","솔레노르의 혼 (1)","아토리우스의 혼 (1)"}},
[7637]={o="아이언포지에 가서 대사제 로한의 퇴마 향로를 가져와야 합니다. 퇴마 향로를 얻으려면 150골드를 기부해야 합니다.",r={"돈: 150 &nbsp; (1)"}},
[7638]={o="스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경과 대화해야 합니다."},
[7639]={o="퇴마 향로를 가지고 스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다."},
[7640]={o="퇴마 향로를 사용하여 테러데일에 고통을 주는 영혼을 몰아내야 합니다. 25명의 테러데일 영혼을 해치운 다음 스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다.",r={"테러데일 영혼 (25)"}},
[7641]={o="스톰윈드의 드워프 지구에 있는 그리만트 엘모어와 대화해야 합니다."},
[7642]={o="룬무늬 옷감 40개, 아케이나이트 주괴 6개, 아서스의 눈물 10개, 스트라솔름 성수 물병 5개 그리고 150골드를 스톰윈드의 드워프 지구에 있는 그리만트 엘모어에게 가져가야 합니다.",r={"스트라솔름 성수 (5)","아서스의 눈물 (10)","룬무늬 옷감 (40)","아케이나이트 주괴 (6)","돈: 150 &nbsp; (1)"}},
[7643]={o="사우스쇼어에 있는 메리데스 칼슨에게 말의 영혼에게 먹일 특별한 말 먹이를 얻어야 합니다. 페랄라스에 있는 혈투의 전장 던전으로 가서 굽이나무 텐드리스를 무찔러야 합니다. 굽이나무 텐드리스를 무찌르고 고대 준마의 영혼이 풀려나면 특별한 말 먹이를 먹여 영혼을 진정시키십시오. 마지막으로 아케이나이트 마갑을 주면 영혼이 축복을 내릴 것입니다.",r={"맛좋은 만나 사료 (1)"}},
[7644]={o="축복받은 아케이나이트 마갑을 가지고 스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 돌아가야 합니다."},
[7645]={o="맛좋은 만나빵 20개를 모아서 힐스브래드 구릉지의 사우스쇼어에 있는 메리데스 칼슨에게 가져가야 합니다. 맛좋은 만나빵은 맛좋은 만나 사료에 꼭 필요한 재료입니다. 맛좋은 만나빵은 은빛 여명회에서 독점적으로 파는 것으로 알려져 있습니다. 메리데스 칼슨에게도 50골드를 주어야만 화가 난 마음을 진정시킬 수 있습니다.",r={"맛좋은 만나빵 (20)","돈: 50 &nbsp; (1)"}},
[7646]={o="스톰윈드의 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 아제로스 다이아몬드와 온전한 검은 다이아몬드를 가져가야 합니다.",r={"아제로스 다이아몬드 (1)","온전한 검은 다이아몬드 (1)"}},
[7647]={o="스칼로맨스에 있는 대형 납골당 지하의 중심부로 가서 예언의 탐지기를 사용해야 합니다. 그러면 영혼들이 나타날 것이니 그들을 해치우십시오. 그들을 해치우면 죽음의 기사 다크리버가 나타날 것이니 그를 물리친 다음 군마의 영혼의 잃어버린 영혼을 되찾아야 합니다. 구원된 군마의 영혼과 축복받은 아케이나이트 마갑을 다크리버 군마의 영혼에게 돌려줘야 합니다.",r={"구원된 군마의 영혼 (1)","축복받은 아케이나이트 마갑 (1)","타락한 군마의 영혼 (1)","예언의 탐지기 (1)"}},
[7648]={o="스톰윈드 빛의 대성당에 있는 그레이슨 섀도브레이커 경에게 아케이나이트 마갑을 가져가야 합니다."},
