[8575]={o="타나리스에 있는 나라인 수스팬시에게 아주어고스의 마법 장부를 전달해야 합니다."},
[8577]={o="나라인 수스팬시가 그의 가장 절친했던 옛 친구 스튜불을 찾아 자신에게서 훔쳐간 수정점 고글을 되찾아 달라고 부탁했습니다."},
[8578]={o="나라인의 수정점 고글을 찾은 후, 타나리스에 있는 나라인 수스팬시에게 돌아가야 합니다.",r={"나라인의 수정점 고글 (1)"}},
[8579]={o="안퀴라즈 안에 노예가 된 우리 형제들이 있다는 것을 느낄 수 있습니다. 하지만 용군단조차 그들을 구하기에는 역부족입니다. 쑨에게 더 이상 접근했다가는 우리 형제들을 괴롭히는 마법의 주문에 걸려 우리도 쑨의 지배를 받게 될 것입니다. 그 고대 신은 우리가 올 것이라는 걸 미리 알고 있었습니다. 더 이상 희망이 없습니다! 당신과 같은 그저 죽을 운명인 자들이 할 수 있을지 모르는 것은 무엇이 다릅니까?",r={"퀴라지 군주의 휘장 (1)"}},
[8580]={o="오그리마의 정기의 골짜기에 있는 박쥐기수 펠레케이키에게 화염초 꽃잎 20개를 가져가야 합니다.",r={"화염초 꽃잎 (20)"}},
[8581]={r={"화염초 꽃잎 (20)"}},
[8582]={o="오그리마의 정기의 골짜기에 있는 연금술사 제젤에게 보라 연꽃 20개를 가져가야 합니다.",r={"보라 연꽃 (20)"}},
[8583]={o="&lt;class&gt;|1이여;여;, 사실 보라 연꽃이 훨씬 더 많이 필요할 것 같네. 보라 연꽃의 새로운 용도를 밝히는 내 연구가 아직 끝난 것은 아니지만 실험을 통해 알아낸 방법 중에 쓸 만한 것도 있었지. 다시 한 번 가서 표본으로 쓸 보라 연꽃을 적어도 20개는 모아다줘야겠어. 다 모으면 내게 돌아오도록.",r={"보라 연꽃 (20)"}},
[8584]={o="타나리스에 있는 나라인 수스팬시가 가젯잔에 있는 더지 퀵클레이브와 대화해 보라고 부탁했습니다."},
[8585]={o="라크마에란의 시체를 손에 넣고 키메로크 안심 20개를 구해서 타나리스에 있는 더지 퀵클레이브에게 돌아가야 합니다.",r={"라크마에란의 시체 (1)","키메로크 안심 (20)"}},
[8586]={o="가젯잔에 있는 더지 퀵클레이브에게 고블린 로켓 연료와 깊은바다 소금을 각각 20개씩 가져가야 합니다.",r={"고블린 로켓 연료 (20)","깊은바다 소금 (20)"}},
[8587]={o="타나리스에 있는 나라인 수스팬시에게 250Kg짜리 닭을 가져가야 합니다."},
[8588]={o="오그리마의 정기의 골짜기에 있는 무두장이 자마니에게 질긴 가죽 10개를 가져가야 합니다.",r={"질긴 가죽 (10)"}},
[8589]={o="네, 그렇습니다. 아직 질긴 가죽이 더 필요해요. 사령관들과 병참장교들은 끝없는 수량을 원하는 것 같아요. 그래도 비행선 기장이 요구하는 것에 비하면 새 발의 피라고 할 수 있죠! 제게 할당된 양을 지금 당장 모아야 합니다. &lt;name&gt;, 최대한 빨리 더 많은 질긴 가죽을 가져다주십시오!",r={"질긴 가죽 (10)"}},
[8590]={o="오그리마의 정기의 골짜기에 있는 하사관 우말라에게 두꺼운 가죽 10개를 가져가야 합니다.",r={"두꺼운 가죽 (10)"}},
[8591]={o="&lt;class&gt;, 보다시피 두꺼운 가죽이 더 많이 필요해. 자네에게 이 일을 다시 한 번 부탁해야겠군. 날 도와주면 자네의 공로를 인정받을 수 있을 거야. 내, 약속하지. 우리에겐 무엇보다도 시간이 중요해! 모든 준비를 마치고 전쟁에 임할 수 있도록 두꺼운 가죽을 가지고 돌아오게!",r={"두꺼운 가죽 (10)"}},
