[99142]={o="[Collect 5 Tomb Weed and deliver them back to Junior Apothecary Holland.]",r={"무덤풀 (5)"}},
[99143]={o="근처 멀록 야영지에서 반짝이는 잡동사니 6개를 모아야 합니다.",r={"반짝이는 잡동사니 (6)"},s="리 브라운",e="리 브라운"},
[99144]={o="[Help Bareth Dawnstone escape Crusader's Outpost, and report his safety to Shari Stilwell in Brill.]",r={"[Escort Bareth Dawnstone out of Crusader's Outpost] (1)"}},
[99152]={o="파괴자 힐다를 위해 희미하게 빛나는 뼈 6개를 모아야 합니다.",r={"희미하게 빛나는 뼈 (6)"}},
[99153]={o="[Find the Hidden Crystal Fragment beneath Shadowvale for Ephram Barbaro.]",r={"빛나는 수정 조각 (1)"}},
[99156]={o="죽음경비병 리니아에게 너덜토막의 심장을 가져가야 합니다.",r={"너덜토막의 심장 (1)"}},
[99158]={o="신부 가빈에게 양초 상자를 가져가야 합니다.",s="막산 앤볼",e="신부 가빈"},
[99159]={o="[Collect 14 pieces of firewood.]",r={"거의 마른 땔감 (14)"},s="신부 가빈",e="신부 가빈"},
[99160]={o="하급 얼음 정령 10마리를 처치해야 합니다.",r={"하급 얼음 정령 (10)"},s="신부 가빈",e="신부 가빈"},
[99161]={o="[Kill Avala and retrieve its core.]",r={"아발라의 핵 (1)"},s="신부 가빈",e="신부 가빈"},
[99162]={o="숨진 산악경비대원들의 소총을 회수해야 합니다.",r={"스톤앤빌의 소총 (1)","선해머의 소총 (1)","콜비어드의 소총 (1)"},s="신부 가빈",e="신부 가빈"},
